BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_ITAM_PARTNER (
 ID VARCHAR2(36 CHAR) PRIMARY KEY, GOVERNING_ORGANIZATION_ID VARCHAR2(36 CHAR) NOT NULL, GOVERNING_SUBDIVISION_ID VARCHAR2(36 CHAR),
 CODE VARCHAR2(32 CHAR) NOT NULL, LEGAL_NAME VARCHAR2(255 CHAR) NOT NULL, LEGAL_NAME_NORMALIZED VARCHAR2(255 CHAR) NOT NULL, DISPLAY_NAME VARCHAR2(255 CHAR) NOT NULL, COUNTRY_CODE CHAR(2 CHAR) NOT NULL,
 AUTHORIZATION_STATUS VARCHAR2(24 CHAR) NOT NULL, VALID_FROM DATE NOT NULL, VALID_UNTIL DATE, OFFICIAL_WEBSITE VARCHAR2(2048 CHAR), SUPPORT_PORTAL VARCHAR2(2048 CHAR),
 VERSION NUMBER(19) DEFAULT 1 NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL,
 CREATED_BY VARCHAR2(36 CHAR) NOT NULL, UPDATED_BY VARCHAR2(36 CHAR) NOT NULL, LAST_REASON VARCHAR2(1024 CHAR) NOT NULL,
 CONSTRAINT UQ_INX_ITAM_PARTNER_CODE UNIQUE(GOVERNING_ORGANIZATION_ID,CODE),
 CONSTRAINT CK_INX_ITAM_PARTNER_UUID CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')),
 CONSTRAINT CK_INX_ITAM_PARTNER_ORG CHECK (REGEXP_LIKE(GOVERNING_ORGANIZATION_ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')),
 CONSTRAINT CK_INX_ITAM_PARTNER_SUB CHECK (GOVERNING_SUBDIVISION_ID IS NULL OR REGEXP_LIKE(GOVERNING_SUBDIVISION_ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')),
 CONSTRAINT CK_INX_ITAM_PARTNER_CODE CHECK (REGEXP_LIKE(CODE,''^[A-Z0-9][A-Z0-9-]{2,31}$'')), CONSTRAINT CK_INX_ITAM_PARTNER_COUNTRY CHECK (REGEXP_LIKE(COUNTRY_CODE,''^[A-Z]{2}$'')),
 CONSTRAINT CK_INX_ITAM_PARTNER_STATUS CHECK (AUTHORIZATION_STATUS IN (''DRAFT'',''PENDING_APPROVAL'',''ACTIVE'',''SUSPENDED'',''RETIRED'')),
 CONSTRAINT CK_INX_ITAM_PARTNER_PERIOD CHECK (VALID_UNTIL IS NULL OR VALID_UNTIL>=VALID_FROM), CONSTRAINT CK_INX_ITAM_PARTNER_VERSION CHECK (VERSION>=1),
 CONSTRAINT CK_INX_ITAM_PARTNER_TIME CHECK (UPDATED_AT>=CREATED_AT))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_ITAM_PARTNER_CAT ON INFRANEXUM_ITAM_PARTNER(GOVERNING_ORGANIZATION_ID,AUTHORIZATION_STATUS,COUNTRY_CODE,ID)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/

BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_ITAM_PARTNER_ROLE (PARTNER_ID VARCHAR2(36 CHAR) NOT NULL, ROLE_CODE VARCHAR2(40 CHAR) NOT NULL, CONSTRAINT PK_INX_ITAM_PARTNER_ROLE PRIMARY KEY(PARTNER_ID,ROLE_CODE), CONSTRAINT FK_INX_ITAM_PARTNER_ROLE FOREIGN KEY(PARTNER_ID) REFERENCES INFRANEXUM_ITAM_PARTNER(ID) ON DELETE CASCADE, CONSTRAINT CK_INX_ITAM_PARTNER_ROLE CHECK (ROLE_CODE IN (''MANUFACTURER'',''SOFTWARE_PUBLISHER'',''SUPPLIER'',''THIRD_PARTY_SUPPORT_PROVIDER'',''INTEGRATOR'',''RECYCLER'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_ITAM_PARTNER_ROLE ON INFRANEXUM_ITAM_PARTNER_ROLE(ROLE_CODE,PARTNER_ID)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/

BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_ITAM_PARTNER_ALIAS (PARTNER_ID VARCHAR2(36 CHAR) NOT NULL, ALIAS_NAME VARCHAR2(255 CHAR) NOT NULL, CONSTRAINT PK_INX_ITAM_PARTNER_ALIAS PRIMARY KEY(PARTNER_ID,ALIAS_NAME), CONSTRAINT FK_INX_ITAM_PARTNER_ALIAS FOREIGN KEY(PARTNER_ID) REFERENCES INFRANEXUM_ITAM_PARTNER(ID) ON DELETE CASCADE)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_ITAM_PARTNER_EXT_ID (PARTNER_ID VARCHAR2(36 CHAR) NOT NULL, AUTHORITY_CODE VARCHAR2(64 CHAR) NOT NULL, EXTERNAL_VALUE VARCHAR2(240 CHAR) NOT NULL, CONSTRAINT PK_INX_ITAM_PARTNER_EXT PRIMARY KEY(PARTNER_ID,AUTHORITY_CODE,EXTERNAL_VALUE), CONSTRAINT FK_INX_ITAM_PARTNER_EXT FOREIGN KEY(PARTNER_ID) REFERENCES INFRANEXUM_ITAM_PARTNER(ID) ON DELETE CASCADE)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_ITAM_PARTNER_ACCRED (PARTNER_ID VARCHAR2(36 CHAR) NOT NULL, POSITION_NO NUMBER(3) NOT NULL, ACCREDITATION_CODE VARCHAR2(120 CHAR) NOT NULL, ISSUER_NAME VARCHAR2(200 CHAR) NOT NULL, VALID_FROM DATE NOT NULL, VALID_UNTIL DATE, EVIDENCE_REFERENCE VARCHAR2(240 CHAR) NOT NULL, CONSTRAINT PK_INX_ITAM_PARTNER_ACC PRIMARY KEY(PARTNER_ID,POSITION_NO), CONSTRAINT FK_INX_ITAM_PARTNER_ACC FOREIGN KEY(PARTNER_ID) REFERENCES INFRANEXUM_ITAM_PARTNER(ID) ON DELETE CASCADE, CONSTRAINT CK_INX_ITAM_PARTNER_APOS CHECK (POSITION_NO BETWEEN 1 AND 128), CONSTRAINT CK_INX_ITAM_PARTNER_APER CHECK (VALID_UNTIL IS NULL OR VALID_UNTIL>=VALID_FROM))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_ITAM_PARTNER_ACC ON INFRANEXUM_ITAM_PARTNER_ACCRED(ACCREDITATION_CODE,PARTNER_ID)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_ITAM_PARTNER_CONTACT (PARTNER_ID VARCHAR2(36 CHAR) NOT NULL, POSITION_NO NUMBER(3) NOT NULL, CONTACT_TYPE VARCHAR2(32 CHAR) NOT NULL, CONTACT_NAME VARCHAR2(160 CHAR) NOT NULL, EMAIL_ADDRESS VARCHAR2(320 CHAR), PHONE_NUMBER VARCHAR2(64 CHAR), CONTACT_URI VARCHAR2(2048 CHAR), CONSTRAINT PK_INX_ITAM_PARTNER_CONTACT PRIMARY KEY(PARTNER_ID,POSITION_NO), CONSTRAINT FK_INX_ITAM_PARTNER_CONTACT FOREIGN KEY(PARTNER_ID) REFERENCES INFRANEXUM_ITAM_PARTNER(ID) ON DELETE CASCADE, CONSTRAINT CK_INX_ITAM_PARTNER_CPOS CHECK (POSITION_NO BETWEEN 1 AND 128), CONSTRAINT CK_INX_ITAM_PARTNER_CHAN CHECK (EMAIL_ADDRESS IS NOT NULL OR PHONE_NUMBER IS NOT NULL OR CONTACT_URI IS NOT NULL))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_ITAM_PARTNER_IDENT (GOVERNING_ORGANIZATION_ID VARCHAR2(36 CHAR) NOT NULL, IDENTITY_TOKEN VARCHAR2(600 CHAR) NOT NULL, PARTNER_ID VARCHAR2(36 CHAR) NOT NULL, CONSTRAINT PK_INX_ITAM_PARTNER_IDENT PRIMARY KEY(GOVERNING_ORGANIZATION_ID,IDENTITY_TOKEN), CONSTRAINT UQ_INX_ITAM_PARTNER_IDENT UNIQUE(PARTNER_ID,IDENTITY_TOKEN), CONSTRAINT FK_INX_ITAM_PARTNER_IDENT FOREIGN KEY(PARTNER_ID) REFERENCES INFRANEXUM_ITAM_PARTNER(ID) ON DELETE CASCADE)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_ITAM_PARTNER_DEDUP (IDEMPOTENCY_KEY VARCHAR2(200 CHAR) PRIMARY KEY, PAYLOAD_SHA256 CHAR(64 CHAR) NOT NULL, OPERATION_NAME VARCHAR2(40 CHAR) NOT NULL, PARTNER_ID VARCHAR2(36 CHAR) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT CK_INX_ITAM_PARTNER_HASH CHECK (REGEXP_LIKE(PAYLOAD_SHA256,''^[0-9a-f]{64}$'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_ITAM_PARTNER_DEDUP ON INFRANEXUM_ITAM_PARTNER_DEDUP(CREATED_AT)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
